// SEPARATE bean — @Async works because the call goes THROUGH the proxy
// If this method were inside SettlementOrchestrator, self-invocation would bypass the proxy!
package com.bank.orchestrator.service;

import lombok.extern.slf4j.Slf4j;
import org.slf4j.MDC;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;

@Service
@Slf4j
public class NotificationService {

    @Async("settlementExecutor")
    public void sendSettlementNotification(String settlementId, String accountId) {
        // This runs on async thread — MDC propagated by MdcTaskDecorator
        String traceId = MDC.get("traceId");
        log.info("[ASYNC] [{}] Sending notification for {} to {}",
            traceId, settlementId, accountId);
        // Send email/SMS/push
        try { Thread.sleep(300); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        log.info("[ASYNC] [{}] Notification sent for {}", traceId, settlementId);
    }
}
